import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 50 Taken for a ride","description":"学习 过去完成时与先后关系，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 50 Taken for a ride","description":"学习 过去完成时与先后关系，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 过去完成时与先后关系，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 49 The end of a dream","link":"/life/english/new-concept/book-2/unit-03/lesson-049"},"next":{"text":"第二册：实践与进步 · Lesson 51 Reward for virtue","link":"/life/english/new-concept/book-2/unit-03/lesson-051"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 49 The end of a dream","link":"/life/english/new-concept/book-2/unit-03/lesson-049"},"next":{"text":"第二册：实践与进步 · Lesson 51 Reward for virtue","link":"/life/english/new-concept/book-2/unit-03/lesson-051"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-050.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-050.md"}'),s={name:"life/english/new-concept/book-2/unit-03/lesson-050.md"};function i(r,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-50-taken-for-a-ride" tabindex="-1">第二册：实践与进步 · Lesson 50 Taken for a ride <a class="header-anchor" href="#第二册-实践与进步-·-lesson-50-taken-for-a-ride" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 50 Taken for a ride&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>乘客误解线路终点，付了车费却没有到达想去的地方；练习行程的先后和被误解的信息。本课的语言观察是：had passed 表下车之前已经经过目的地；did not realise 描述当时的认知。先后关系应靠时间线核对，不只看句子排列顺序。完成学习后，请讲一次坐过站经历，用过去完成时说明发现问题前已经发生的事。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>route</td><td>/ruːt/</td><td>n.</td><td>路线</td><td>plan a route</td></tr><tr><td>fare</td><td>/feə/</td><td>n.</td><td>车费</td><td>pay the fare</td></tr><tr><td>conductor</td><td>/kənˈdʌktə/</td><td>n.</td><td>售票员；指挥</td><td>a bus conductor</td></tr><tr><td>destination</td><td>/ˌdestɪˈneɪʃən/</td><td>n.</td><td>目的地</td><td>reach a destination</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>get off — 下车，不用于上飞机</li><li>on the way to — 在去……的路上</li></ul><h2 id="语法讲解-过去完成时与先后关系" tabindex="-1">语法讲解：过去完成时与先后关系 <a class="header-anchor" href="#语法讲解-过去完成时与先后关系" aria-label="Permalink to &quot;语法讲解：过去完成时与先后关系&quot;">​</a></h2><p>过去完成时由 had 加过去分词构成，表示在另一个过去参照点之前发生的事。必须先建立“过去的那个时刻”，否则不宜只因事件发生得很久以前就使用 had done。before 或 after 已清楚说明先后时，一般过去时也可能成立；过去完成时则进一步强调较早的动作已完成。叙事回到主时间线后通常继续使用一般过去时。本课应用：had passed 表下车之前已经经过目的地；did not realise 描述当时的认知。先后关系应靠时间线核对，不只看句子排列顺序。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>By the time I asked, the bus had passed my stop.</p></blockquote><p>等我开口询问时，公交车已经驶过了我要下的站。</p><p>By the time 从句 asked 定位过去时刻，had passed 说明更早已发生的事件；my stop 是目的站。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>get out of 常用于小汽车，get off 常用于公共汽车；不能在所有交通方式中机械互换。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>注意 passed 与 past 常同音；靠句法识别 passed 是谓语的一部分。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>By the time I asked, the bus had passed my stop. The driver showed me the return route. I bought another ticket and checked every stop.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>讲一次坐过站经历，用过去完成时说明发现问题前已经发生的事。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：By the time 从句 asked 定位过去时刻，had passed 说明更早已发生的事件；my stop 是目的站。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：get out of 常用于小汽车，get off 常用于公共汽车；不能在所有交通方式中机械互换。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 pass：The bus had ___ my stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> passed</p><p><strong>解析：</strong> had 后用过去分词 passed。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>司机提供了什么帮助？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He showed the return route.</p><p><strong>解析：</strong> 并没有声称司机调头或退还车费。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>补全：I got ___ the bus at the next stop.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> off</p><p><strong>解析：</strong> 从公共汽车下车通常用 get off。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去完成时与先后关系。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-049">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-051">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(s,[["render",i]]);export{u as __pageData,f as default};
